&lt;li&gt;&lt;a href=&quot;#_hệ_thống_bản_thể_luận_mới_nổi_khi_các_bài_viết_tự_nhóm_lại_mà_không_cần_biết_nhau&quot;&gt;Hệ Thống Bản Thể Luận Mới Nổi: Khi Các Bài Viết Tự Nhóm Lại Mà Không Cần Biết Nhau&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_hợp_đồng_dag_ai_nhập_ai&quot;&gt;Hợp đồng DAG: Ai nhập ai&lt;/a&gt;&lt;/li&gt;
