&lt;div id=&quot;toctitle&quot;&gt;Mục lục&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_bối_cảnh_không_phải_là_một_bệ_thử_mà_là_một_công_trường&quot;&gt;Bối cảnh: không phải là một bệ thử, mà là một công trường&lt;/a&gt;&lt;/li&gt;
