  file &quot;PROCEDURES.adoc\n(6 bước + LAZY/EAGER)&quot; as PRO
  file &quot;SESSIONS_HISTORY.adoc\n(Tất cả các phiên)&quot; as HIS

  folder &quot;sessions/&quot; as SESS {
    file &quot;1-chore-migration.adoc&quot; as S1
