&lt;li&gt;&lt;a href=&quot;#_lọc_theo_loại_nút_và_độ_tin_cậy&quot;&gt;Lọc theo loại nút và độ tin cậy&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_thư_mục_đầu_ra_tùy_chỉnh&quot;&gt;Thư mục đầu ra tùy chỉnh&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tham_chiếu_đầy_đủ_các_thuộc_tính&quot;&gt;Tham chiếu đầy đủ các thuộc tính&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pipeline_hoàn_chỉnh_trong_một_workflow_gradle&quot;&gt;Pipeline hoàn chỉnh trong một workflow Gradle&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
