&lt;li&gt;&lt;a href=&quot;#_những_cạm_bẫy_và_lỗi_thường_gặp&quot;&gt;Những cạm bẫy và lỗi thường gặp&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_nhầm_lẫn_giữa_ctrlz_và_ctrlc&quot;&gt;Nhầm lẫn giữa &lt;code&gt;Ctrl+Z&lt;/code&gt; và `Ctrl+C&lt;/a&gt;&lt;/li&gt;
