&lt;li&gt;&lt;a href=&quot;#_tiện_ích_mở_rộng_custom_css_yêu_cầu_phải_được_kích_hoạt_rõ_ràng&quot;&gt;Tiện ích mở rộng Custom CSS yêu cầu phải được kích hoạt rõ ràng&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_một_script_cập_nhật_là_không_thể_thiếu&quot;&gt;Một script cập nhật là không thể thiếu&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
