&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_cách_tiếp_cận_trực_quan_nhưng_không_hiệu_quả&quot;&gt;Cách tiếp cận Trực quan nhưng Không hiệu quả&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_hiểu_về_sự_kiện_domcontentloaded&quot;&gt;Hiểu về Sự kiện DOMContentLoaded&lt;/a&gt;&lt;/li&gt;
