&lt;li&gt;&lt;a href=&quot;#_các_nỗ_lực_giải_quyết_không_hiệu_quả&quot;&gt;Các Nỗ lực Giải quyết Không hiệu quả&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_giải_pháp_thực_sự_hành_động_sớm_hơn&quot;&gt;Giải Pháp Thực Sự: Hành Động Sớm Hơn&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_giải_pháp_tải_trước_early_loading&quot;&gt;Giải pháp: Tải trước (Early Loading)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_nguyên_lý_cơ_bản&quot;&gt;Nguyên lý Cơ bản&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tại_sao_head_là_nơi_lý_tưởng&quot;&gt;Tại sao &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; là Nơi Lý Tưởng&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kiến_trúc_giải_pháp_ba_lớp&quot;&gt;Kiến trúc Giải pháp Ba Lớp&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bước_1_lưu_lựa_chọn_của_người_dùng&quot;&gt;Bước 1: Lưu Lựa chọn của Người dùng&lt;/a&gt;
