&lt;li&gt;&lt;a href=&quot;#_tiến_thoái_lưỡng_nan_trong_logging&quot;&gt;Tiến thoái lưỡng nan trong Logging&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_những_ý_tưởng_tưởng_chừng_là_hay_nhưng_thực_ra_là_sai&quot;&gt;Những Ý Tưởng Tưởng Chừng Là Hay Nhưng Thực Ra Là Sai&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
