&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Mục lục&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_mục_tiêu&quot;&gt;Mục tiêu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cấu_hình_khai_báo&quot;&gt;Cấu hình khai báo&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kiến_trúc_của_plugin&quot;&gt;Kiến trúc của plugin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_định_nghĩa_về_phần_mở_rộng_dsl&quot;&gt;Định nghĩa về phần mở rộng DSL&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_định_nghĩa_tác_vụ_tùy_chỉnh&quot;&gt;Định nghĩa tác vụ tùy chỉnh&lt;/a&gt;&lt;/li&gt;
