&lt;li&gt;&lt;a href=&quot;#_dsl_cấu_hình_kotlin&quot;&gt;DSL Cấu hình Kotlin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kiểm_thử_đơn_vị_với_mockito&quot;&gt;Kiểm thử đơn vị với Mockito&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dependencies&quot;&gt;Dependencies&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kiểm_tra_hành_vi_git&quot;&gt;Kiểm tra hành vi Git&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kết_luận&quot;&gt;Kết luận&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_các_bước_tiếp_theo&quot;&gt;Các bước tiếp theo&lt;/a&gt;&lt;/li&gt;
