&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;generiques&quot;&gt;Thông tin chung&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Generics cho phép tạo các thành phần có thể tái sử dụng với các kiểu dữ liệu động.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ví dụ về báo giá:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;const identity = &amp;lt;T&amp;gt;(arg: T): T =&amp;gt; arg;

const output = identity&amp;lt;string&amp;gt;(&quot;hello&quot;);
console.log(output);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
