&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_répository_et_code_sample&quot;&gt;Répository et code sample&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;github repository: &lt;a href=&quot;https://github.com/cheroliv/html-codebase&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;html-codebase&lt;/a&gt;&lt;/p&gt;
