&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_đoạn_mã_linh_tinh&quot;&gt;Đoạn mã linh tinh&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_map_reduce&quot;&gt;map reduce&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Chuyển đổi một danh sách &lt;code&gt;bite&lt;/code&gt; thành một danh sách &lt;code&gt;string&lt;/code&gt; và tóm tắt danh sách &lt;code&gt;string&lt;/code&gt; đó&lt;br&gt;
trong một chuỗi chứa phép nối. Cách ghi log request đã gửi (&lt;code&gt;requestBodyContent:byte[]&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;log.info(
    requestBodyContent!!.map { it.toInt().toChar().toString() }
        .reduce { request: String, s: String -&amp;gt; request + s }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_enum_và_sealed_classes&quot;&gt;enum và sealed classes&lt;/h3&gt;
