&lt;li&gt;&lt;a href=&quot;#_ghi_đè_property_param_component_bằng_dòng_lệnh&quot;&gt;Ghi đè property &lt;code&gt;param_component&lt;/code&gt; bằng dòng lệnh:&lt;/a&gt;&lt;/li&gt;
